<!-- --------- новый код chat: история поступлений и использования с переходом в книгу -->
<template><WorkOrderDialog :title="`История: ${material.name}`" @close="$emit('close')"><div v-if="error" class="alert alert-danger">{{ error }}</div><div v-if="loading">Загрузка…</div><template v-else><h3 class="fs-6">Поступления</h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Дата</th><th>Количество, {{ unit }}</th><th></th></tr></thead><tbody><tr v-for="row in data.receipts" :key="row.ID"><td>{{ row.date }}</td><td>{{ quantityDisplay(row.quantity_thousandths) }}</td><td class="text-end"><button class="btn btn-link btn-sm" @click="$emit('edit',row,false)">Изменить</button><button class="btn btn-link text-danger btn-sm" @click="remove(row)">Удалить</button></td></tr></tbody></table></div><p v-if="!data.receipts.length" class="text-secondary">Поступлений нет.</p><h3 class="fs-6 mt-3">Использование</h3><div class="table-responsive"><table class="table table-sm"><thead><tr><th>День / смена</th><th>Работа / позиция</th><th>Количество, {{ unit }}</th></tr></thead><tbody><tr v-for="u in data.usages" :key="u.ID"><td><router-link :to="{name:'agreement-work-orders',params:{id:agreementId},query:{book:u.book_id,date:u.date}}" @click="$emit('close')">{{ u.date }} / {{ u.number }}</router-link></td><td>{{ u.task_name }}<div class="text-secondary">{{ u.block_name }} · {{ u.position_number }} — {{ u.position_name }}</div></td><td>{{ quantityDisplay(u.quantity_thousandths) }}</td></tr></tbody></table></div><p v-if="!data.usages.length" class="text-secondary">Материал ещё не использовался.</p></template></WorkOrderDialog></template>
<script setup>
import {ref,onMounted} from 'vue';import api from '../../../api';import WorkOrderDialog from './WorkOrderDialog.vue';import {quantityDisplay,workError} from './workOrderHelpers';const props=defineProps({agreementId:[String,Number],material:Object,unit:String});const emit=defineEmits(['close','edit']);const data=ref({receipts:[],usages:[]}),loading=ref(true),error=ref('');
onMounted(async()=>{try{data.value=(await api.get(`/agreements/${props.agreementId}/warehouse/${props.material.ID}/history`)).data;}catch(e){error.value=workError(e);}finally{loading.value=false;}});
const remove=row=>{if(confirm('Удалить это поступление? При нехватке остатка потребуется выбрать списания для удаления из работ.'))emit('edit',row,true);};
</script>
<!-- --------- конец нового кода chat -->
